import (
	context "context"
	fern "github.com/cli-oauth/fern"
	fernclient "github.com/cli-oauth/fern/client"
	option "github.com/cli-oauth/fern/option"
)

client := fernclient.NewClient(
	option.WithClientCredentials(
		"<YOUR_CLIENT_ID>",
		"<YOUR_CLIENT_SECRET>",
	),
)
response, err := client.Auth.GetToken(
	context.TODO(),
	&fern.GetTokenAuthRequest{
		ClientID:     "client_id",
		ClientSecret: "client_secret",
		Scopes:       "scopes",
		GrantType:    fern.GetTokenAuthRequestGrantTypeClientCredentials,
		Tenant:       "tenant",
	},
)
